function Stat({icon,value,label}:{icon:React.ReactNode;value:number;label:string}){return <div className="stat"><div>{icon}</div><b>{value}</b><span>{label}</span></div>}

function HistoryPage({user,open}:{user:User;open:(id:string)=>void}){const[data,setData]=useState<Work[]>([]),[users,setUsers]=useState<User[]>([]),[loading,setLoading]=useState(true),[q,setQ]=useState(""),[type,setType]=useState("ALL"),[status,setStatus]=useState("ALL"),[assigneeId,setAssigneeId]=useState("ALL"),[from,setFrom]=useState(""),[to,setTo]=useState("");useEffect(()=>{Promise.all([api("/history").then(setData),user.role!=="EMPLOYEE"?api("/users").then(setUsers):Promise.resolve()]).finally(()=>setLoading(false))},[]);const filtered=useMemo(()=>data.filter(w=>{if(type!=="ALL"&&w.type!==type)return false;if(status!=="ALL"&&w.status!==status)return false;if(assigneeId!=="ALL"&&!assignees(w).some(u=>u.id===assigneeId))return false;if(q.trim()&&!`${w.title} ${w.description||""} ${assignees(w).map(x=>x.name).join(" ")}`.toLowerCase().includes(q.trim().toLowerCase()))return false;const d=new Date(w.completedAt||w.dueDate||0);if(from&&d<new Date(from+"T00:00:00"))return false;if(to&&d>new Date(to+"T23:59:59"))return false;return true}),[data,q,type,status,assigneeId,from,to]);const reset=()=>{setQ("");setType("ALL");setStatus("ALL");setAssigneeId("ALL");setFrom("");setTo("")};return <><div className="hero-row"><div><h1>Історія</h1><p className="muted">Виконані та прострочені записи старше одного місяця.</p></div></div><section className="panel history-filter"><div className="filter-title"><Filter/><b>Фільтр архіву</b><span>{filtered.length} з {data.length}</span></div><div className="history-filter-grid"><label className="search-field">Пошук<div><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Назва, опис або працівник"/></div></label><label>Тип<select value={type} onChange={e=>setType(e.target.value)}><option value="ALL">Усі типи</option><option value="CHECKLIST">Чеклісти</option><option value="TASK">Завдання</option></select></label><label>Статус<select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">Усі статуси</option><option value="COMPLETED">Виконані</option><option value="OVERDUE">Прострочені</option></select></label>{user.role!=="EMPLOYEE"&&<label>Виконавець<select value={assigneeId} onChange={e=>setAssigneeId(e.target.value)}><option value="ALL">Усі працівники</option>{users.map(u=><option value={u.id} key={u.id}>{u.name} — {u.position}</option>)}</select></label>}<label>Від<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>До<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><button className="secondary filter-reset" onClick={reset}>Скинути</button></div></section>{loading?<div className="empty">Завантаження…</div>:<div className="cards">{filtered.map(w=><WorkCard key={w.id} w={w} open={()=>open(w.id)}/>)}{!filtered.length&&<div className="empty">За вибраними фільтрами нічого не знайдено.</div>}</div>}</>}

function WorkCard({w,open}:{w:Work;open:()=>void}){const done=w.items?.filter(i=>i.status==="DONE").length||0,blocked=w.items?.filter(i=>i.status==="BLOCKED").length||0,pct=w.type==="TASK"?(w.status==="COMPLETED"?100:0):(w.items?.length?Math.round(done/w.items.length*100):0),people=assignees(w);return <button className={`check-card ${w.status==="OVERDUE"?"overdue-card":""} ${w.status==="DEFERRED"?"deferred-card":""} ${w.status==="COMPLETED"?"completed-card":""}`} onClick={open}><div className="check-top"><div className="type-stack"><span className={`kind ${w.type.toLowerCase()}`}>{w.type==="TASK"?<FileCheck2/>:<ClipboardCheck/>}{w.type==="TASK"?"Завдання":"Чекліст"}</span><Status status={w.status}/></div>{w.recurrence!=="NONE"&&<span className="repeat"><RefreshCcw/> {w.recurrence==="MONTHLY"?"Щомісяця":w.recurrence==="WEEKLY"?"Щотижня":w.recurrence==="CUSTOM_DAYS"?`Кожні ${w.recurrenceDays||1} дн.`:""}</span>}</div><h3>{w.title}</h3><p>{w.description||"Без опису"}</p>{w.type==="CHECKLIST"&&<><div className="progress"><i style={{width:`${pct}%`}}/></div><div className="check-meta"><span><CheckCircle2/>{done}/{w.items?.length||0}</span>{blocked>0&&<span className="danger"><AlertTriangle/>{blocked}</span>}{w.status!=="DEFERRED"&&<><span><CalendarClock/>Старт: {fmt(w.startDate)}</span><span><Clock3/>До: {fmt(w.dueDate)}</span></>}</div></>}{w.type==="TASK"&&<div className="check-meta task-meta">{w.status!=="DEFERRED"&&<><span><CalendarClock/>Старт: {fmt(w.startDate)}</span><span><Clock3/>До: {fmt(w.dueDate)}</span></>}{w.taskBlockedReason&&<span className="danger"><AlertTriangle/>Є причина невиконання</span>}</div>}<div className="creator-line"><UserCog/>Створив: <b>{w.createdBy?.name||"—"}</b></div><div className="assignee multi-assignee"><div className="avatar-stack">{people.slice(0,3).map((u,n)=><div className="avatar small" key={u.id} style={{zIndex:5-n}}>{u.name[0]}</div>)}{people.length>3&&<div className="avatar small more">+{people.length-3}</div>}</div><div><b>{people.map(x=>x.name).join(", ")}</b><span>{people.length===1?people[0].position:`${people.length} виконавців`}</span></div></div></button>}
function Status({status}:{status:Status}){const names:any={SCHEDULED:"Заплановано",DEFERRED:"Відкладені",OPEN:"В роботі",IN_PROGRESS:"В роботі",BLOCKED:"Є проблема",COMPLETED:"Виконані",OVERDUE:"Прострочені"};return <span className={`status ${status.toLowerCase()}`}>{names[status]}</span>}
function PendingBox({rows,open,reload}:{rows:PendingRequest[];open:(id:string)=>void;reload:()=>void}){return <section className="pending-box"><div className="section-head"><div><h3>Запити на відтермінування</h3><span>{rows.length} очікує рішення</span></div></div><div className="pending-list">{rows.map(r=><div className="pending-row" key={r.id}><div><b>{r.checklist.title}</b><span>{r.requester.name}: {r.reason}</span><small>Поточний термін: {fmt(r.checklist.dueDate)}</small></div><div className="pending-actions"><button onClick={()=>open(r.checklist.id)}>Відкрити</button><DecisionButton request={r} reload={reload}/></div></div>)}</div></section>}
function DecisionButton({request,reload}:{request:PendingRequest;reload:()=>void}){const[show,setShow]=useState(false),[newDueDate,setNewDueDate]=useState(toLocalInput(request.checklist.dueDate)),[note,setNote]=useState("");const decide=async(decision:"APPROVED"|"REJECTED")=>{try{await api(`/postpone-requests/${request.id}/decision`,{method:"POST",body:JSON.stringify({decision,newDueDate:decision==="APPROVED"?new Date(newDueDate).toISOString():undefined,note})});setShow(false);reload()}catch(e:any){alert(e.message)}};return <>{<button className="primary" onClick={()=>setShow(true)}>Рішення</button>}{show&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>Рішення щодо відтермінування</h2><p>{request.checklist.title}</p></div><button className="icon" onClick={()=>setShow(false)}><X/></button></div><div className="info-note"><b>Причина працівника</b><p>{request.reason}</p></div><label>Новий термін<input type="datetime-local" value={newDueDate} onChange={e=>setNewDueDate(e.target.value)}/></label><label>Коментар керівника (необов'язково)<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Буде додано до системного коментаря про відтермінування"/></label><div className="modal-actions split"><button onClick={()=>decide("REJECTED")}>Не погодити</button><button className="primary" onClick={()=>decide("APPROVED")}>Погодити новий термін</button></div></div></div>}</>}

function WorkDetail({id,user,back,changed}:{id:string;user:User;back:()=>void;changed:()=>void}){const[w,setW]=useState<Work|null>(null),[comment,setComment]=useState(""),[blocked,setBlocked]=useState<Item|null>(null),[reason,setReason]=useState(""),[taskAction,setTaskAction]=useState<"DONE"|"BLOCKED"|null>(null),[taskText,setTaskText]=useState(""),[postpone,setPostpone]=useState(false),[postponeReason,setPostponeReason]=useState(""),[postponeDue,setPostponeDue]=useState(""),[edit,setEdit]=useState(false);const load=()=>api(`/checklists/${id}`).then(setW);useEffect(()=>{load()},[id]);if(!w)return <div className="empty">Завантаження…</div>;const canEdit=user.role!=="EMPLOYEE";const addToTemplate=async()=>{try{const name=window.prompt(ui("Назва шаблону","Template name"),w.title);if(!name)return;await api(`/templates/from-checklist/${w.id}`,{method:"POST",body:JSON.stringify({name})});alert(ui("Шаблон додано.","Template added."))}catch(e:any){alert(e.message)}};const setItem=async(item:Item,status:Item["status"],blockedReason?:string)=>{try{await api(`/items/${item.id}`,{method:"PATCH",body:JSON.stringify({status,blockedReason})});setBlocked(null);setReason("");load();changed()}catch(e:any){alert(e.message)}};const photo=async(item:Item,file:File)=>{const fd=new FormData();fd.append("photo",file);try{await api(`/items/${item.id}/photo`,{method:"POST",body:fd});load()}catch(e:any){alert(e.message)}};const addComment=async()=>{if(!comment.trim())return;await api(`/checklists/${id}/comments`,{method:"POST",body:JSON.stringify({text:comment})});setComment("");load()};const taskSave=async()=>{try{await api(`/checklists/${id}/task-state`,{method:"POST",body:JSON.stringify({status:taskAction,comment:taskText})});setTaskAction(null);setTaskText("");load();changed()}catch(e:any){alert(e.message)}};const directPostpone=user.role!=="EMPLOYEE"&&w.createdBy?.id===user.id;const sendPostpone=async()=>{try{await api(`/checklists/${id}/postpone`,{method:"POST",body:JSON.stringify({reason:postponeReason,newDueDate:directPostpone&&postponeDue?new Date(postponeDue).toISOString():undefined})});setPostpone(false);setPostponeReason("");setPostponeDue("");load();changed()}catch(e:any){alert(e.message)}};const done=w.items?.filter(i=>i.status==="DONE").length||0,pending=w.postponeRequests?.find(r=>r.status==="PENDING"),people=assignees(w);return <><button className="back" onClick={back}>← Назад</button><div className="detail-head"><div><div className="detail-badges"><span className={`kind ${w.type.toLowerCase()}`}>{w.type==="TASK"?<FileCheck2/>:<ClipboardCheck/>}{w.type==="TASK"?"Завдання":"Чекліст"}</span><Status status={w.status}/></div><h1>{w.title}</h1><p className="muted">{w.description||"Без опису"}</p><div className="detail-created">Створив: <b>{w.createdBy?.name||"—"}</b></div><div className="detail-actions"><button className="secondary" disabled={!!pending||w.status==="COMPLETED"} onClick={()=>{setPostponeDue(w.dueDate?toLocalInput(w.dueDate):"");setPostpone(true)}}><CalendarClock/> {pending?"Очікує погодження":"Відтермінувати"}</button>{canEdit&&<><button className="secondary" onClick={()=>setEdit(true)}><Pencil/>Редагувати</button><button className="secondary" onClick={addToTemplate}><Plus/>Додати в шаблон</button></>}</div></div><div className="deadline"><span>Початок</span><b>{fmt(w.startDate)}</b><span>Термін виконання</span><b>{fmt(w.dueDate)}</b><small>{people.map(x=>`${x.name} · ${x.position}`).join(" • ")}</small></div></div>{pending&&<div className="notice"><CalendarClock/><div><b>Запит на відтермінування очікує рішення</b><span>{pending.reason}</span></div></div>}{w.type==="CHECKLIST"?<ChecklistBody w={w} done={done} setItem={setItem} setBlocked={i=>{setBlocked(i);setReason(i.blockedReason||"")}} photo={photo}/>:<TaskBody w={w} action={a=>{setTaskAction(a);setTaskText(a==="BLOCKED"?(w.taskBlockedReason||""):(w.taskComment||""))}}/>}<section className="panel comments standalone"><h2><MessageSquare/> Коментарі</h2><div className="comment-list">{w.comments?.map(x=><div className={`comment ${x.text.startsWith("Було відтерміновано до")?"system-comment":""}`} key={x.id}><div className="avatar small">{x.author.name[0]}</div><div><b>{x.author.name}</b><span>{new Date(x.createdAt).toLocaleString(getLang()==="uk"?"uk-UA":"en-GB",{hour12:false})}</span><p>{x.text}</p></div></div>)}{!w.comments?.length&&<p className="muted">Коментарів поки немає.</p>}</div><textarea placeholder="Написати коментар…" value={comment} onChange={e=>setComment(e.target.value)}/><button className="primary" onClick={addComment}>Додати коментар</button></section>{blocked&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>Причина невиконання</h2><p>Вкажіть, чому пункт неможливо виконати.</p></div><button className="icon" onClick={()=>setBlocked(null)}><X/></button></div><textarea autoFocus value={reason} onChange={e=>setReason(e.target.value)}/><div className="modal-actions"><button onClick={()=>setBlocked(null)}>Скасувати</button><button className="warning-btn" disabled={!reason.trim()} onClick={()=>setItem(blocked,"BLOCKED",reason)}>Зберегти причину</button></div></div></div>}{taskAction&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>{taskAction==="DONE"?"Завдання виконано":"Не можу виконати завдання"}</h2><p>{taskAction==="DONE"?"Коментар необов'язковий.":"Причина невиконання обов'язкова."}</p></div><button className="icon" onClick={()=>setTaskAction(null)}><X/></button></div><textarea autoFocus placeholder={taskAction==="DONE"?"Що було зроблено (необов'язково)…":"Вкажіть причину…"} value={taskText} onChange={e=>setTaskText(e.target.value)}/><div className="modal-actions"><button onClick={()=>setTaskAction(null)}>Скасувати</button><button className={taskAction==="DONE"?"primary":"warning-btn"} disabled={taskAction==="BLOCKED"&&!taskText.trim()} onClick={taskSave}>Підтвердити</button></div></div></div>}{postpone&&<div className="modal-backdrop"><div className="modal small-modal"><div className="modal-head"><div><h2>{directPostpone?"Відтермінувати":"Запит на відтермінування"}</h2><p>{directPostpone?"Ви створили цей запис, тому погодження не потрібне.":"Дедлайн не зміниться, доки керівник не погодить запит."}</p></div><button className="icon" onClick={()=>setPostpone(false)}><X/></button></div>{directPostpone&&<label>Новий термін<input type="datetime-local" value={postponeDue} onChange={e=>setPostponeDue(e.target.value)}/></label>}<label>Причина / коментар<textarea autoFocus value={postponeReason} onChange={e=>setPostponeReason(e.target.value)} placeholder="Чому потрібне відтермінування?"/></label><div className="modal-actions"><button onClick={()=>setPostpone(false)}>Скасувати</button><button className="primary" disabled={postponeReason.trim().length<3||(directPostpone&&!postponeDue)} onClick={sendPostpone}>{directPostpone?"Відтермінувати":"Надіслати запит"}</button></div></div></div>}{edit&&<WorkEditor work={w} close={()=>setEdit(false)} done={()=>{setEdit(false);load();changed()}}/>}</>}
function ChecklistBody({w,done,setItem,setBlocked,photo}:{w:Work;done:number;setItem:(i:Item,s:Item["status"],r?:string)=>void;setBlocked:(i:Item)=>void;photo:(i:Item,f:File)=>void}){const pct=Math.round(done/(w.items?.length||1)*100)||0;return <section className="panel"><div className="section-head"><div><h2>Пункти чекліста</h2><span>{done} з {w.items?.length||0} виконано</span></div><b>{pct}%</b></div><div className="progress large"><i style={{width:`${pct}%`}}/></div><div className="item-list">{w.items?.map((i,n)=><div className={`item-row ${i.status.toLowerCase()}`} key={i.id}><div className="item-num">{n+1}</div><div className="item-body"><b>{i.title}</b>{i.description&&<p>{i.description}</p>}{i.status==="BLOCKED"&&<div className="reason"><AlertTriangle/>{i.blockedReason}</div>}{i.attachments?.length>0&&<div className="photos">{i.attachments.map(a=><a href={a.filePath} target="_blank" rel="noreferrer" key={a.id}><img src={a.filePath}/></a>)}</div>}<div className="item-actions"><button onClick={()=>setItem(i,"DONE")} className={i.status==="DONE"?"selected":""}><CheckCircle2/>Виконано</button><button onClick={()=>setBlocked(i)} className={i.status==="BLOCKED"?"selected warning":""}><AlertTriangle/>Не можу виконати</button><label className="upload"><Camera/>Фото<input type="file" accept="image/*" capture="environment" onChange={e=>e.target.files?.[0]&&photo(i,e.target.files[0])}/></label>{i.requiresPhoto&&<span className="required">Фото обов'язкове</span>}</div></div></div>)}</div></section>}
function TaskBody({w,action}:{w:Work;action:(a:"DONE"|"BLOCKED")=>void}){return <section className="panel task-panel"><div className="task-icon"><FileCheck2/></div><div><h2>Завдання</h2><p className="muted">{w.description||"Опис не вказаний"}</p>{w.taskComment&&<div className="result-box success"><b>Коментар після виконання</b><p>{w.taskComment}</p></div>}{w.taskBlockedReason&&<div className="result-box fail"><b>Причина невиконання</b><p>{w.taskBlockedReason}</p></div>}{w.status!=="COMPLETED"&&<div className="task-actions"><button className="primary" onClick={()=>action("DONE")}><CheckCircle2/>Виконані</button><button className="warning-btn" onClick={()=>action("BLOCKED")}><AlertTriangle/>Не можу виконати</button></div>}</div></section>}

function UsersPage({user}:{user:User}){const[users,setUsers]=useState<User[]>([]),[show,setShow]=useState(false),[edit,setEdit]=useState<User|null>(null);const load=()=>api("/users").then(setUsers);useEffect(()=>{load()},[]);const toggle=async(u:User)=>{try{await api(`/users/${u.id}`,{method:"PATCH",body:JSON.stringify({active:u.active===false})});load()}catch(e:any){alert(e.message)}};const remove=async(u:User)=>{if(!confirm(`${ui("Видалити користувача","Delete user")} ${u.name}?`))return;try{await api(`/users/${u.id}`,{method:"DELETE"});load()}catch(e:any){alert(e.message)}};return <><div className="hero-row"><div><h1>Користувачі</h1><p className="muted">Працівники, посади, групи та рівні доступу.</p></div>{user.role==="ADMIN"&&<button className="primary" onClick={()=>setShow(true)}><Plus/>Додати користувача</button>}</div><div className="user-grid">{users.map(u=><div className={`user-card ${u.active===false?"user-disabled":""}`} key={u.id}><div className="avatar large">{u.name[0]}</div><div className="user-main"><h3>{u.name}</h3><p>@{u.username}</p><div className="user-tags"><span><Briefcase/>{u.position}</span><span><ShieldCheck/>{roleLabel(u.role)}</span><span>{u.active===false?"Заблокований":"Активний"}</span>{u.groups?.map(g=><span key={g.group.id}>{g.group.name}</span>)}</div></div>{user.role==="ADMIN"&&<div className="user-actions"><button className="icon" title="Редагувати" onClick={()=>setEdit(u)}><UserCog/></button><button className="icon" title={u.active===false?"Розблокувати":"Заблокувати"} onClick={()=>toggle(u)}>{u.active===false?<Unlock/>:<Lock/>}</button><button className="icon danger-icon" title="Видалити" onClick={()=>remove(u)}><Trash2/></button></div>}<span className={u.active===false?"dot off":"dot"}/></div>)}</div>{show&&<UserEditor close={()=>setShow(false)} done={()=>{setShow(false);load()}}/>}{edit&&<UserEditor target={edit} close={()=>setEdit(null)} done={()=>{setEdit(null);load()}}/>}</>}
function UserEditor({target,close,done}:{target?:User;close:()=>void;done:()=>void}){const[groups,setGroups]=useState<WorkGroup[]>([]);const[f,setF]=useState({name:target?.name||"",username:target?.username||"",password:"",position:target?.position||"",role:target?.role||"EMPLOYEE" as Role,telegramChatId:target?.telegramChatId||"",canViewGroupTasks:target?.canViewGroupTasks||false,groupIds:target?.groups?.map(g=>g.group.id)||[] as string[]});useEffect(()=>{api("/groups").then(setGroups)},[]);const toggleGroup=(id:string)=>setF(v=>({...v,groupIds:v.groupIds.includes(id)?v.groupIds.filter(x=>x!==id):[...v.groupIds,id]}));const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const payload:any={...f};if(target&&!f.password)delete payload.password;await api(target?`/users/${target.id}`:"/users",{method:target?"PATCH":"POST",body:JSON.stringify(payload)});done()}catch(e:any){alert(e.message)}};return <div className="modal-backdrop"><form className="modal" onSubmit={submit}><div className="modal-head"><div><h2>{target?"Редагування користувача":"Новий користувач"}</h2><p>{target?"Змініть дані, групи та права доступу.":"Створіть обліковий запис працівника."}</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="form-grid"><label>Ім'я<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label>Ім'я користувача<input required minLength={3} value={f.username} onChange={e=>setF({...f,username:e.target.value})}/></label><label>Посада<input required value={f.position} onChange={e=>setF({...f,position:e.target.value})}/></label><label>Роль<select value={f.role} onChange={e=>setF({...f,role:e.target.value as Role})}><option value="EMPLOYEE">Працівник</option><option value="MANAGER">Менеджер</option><option value="ADMIN">Адміністратор</option></select></label><label>Telegram Chat ID <small>(необов'язково)</small><input value={f.telegramChatId} onChange={e=>setF({...f,telegramChatId:e.target.value})}/></label><label>{target?"Новий тимчасовий пароль":"Тимчасовий пароль"}<input required={!target} minLength={8} type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})}/></label><div className="full group-editor"><span className="field-label">Групи</span><div className="group-checks">{groups.map(g=><label className="check" key={g.id}><input type="checkbox" checked={f.groupIds.includes(g.id)} onChange={()=>toggleGroup(g.id)}/>{g.name}</label>)}{!groups.length&&<span className="muted">Груп немає.</span>}</div></div>{f.role==="EMPLOYEE"&&<label className="full check group-visibility"><input type="checkbox" checked={f.canViewGroupTasks} onChange={e=>setF({...f,canViewGroupTasks:e.target.checked})}/> Бачити завдання інших працівників у групі</label>}</div><div className="modal-actions"><button type="button" onClick={close}>Скасувати</button><button className="primary">Зберегти</button></div></form></div>}

function GroupsPage({user}:{user:User}){const[groups,setGroups]=useState<WorkGroup[]>([]),[name,setName]=useState("");const load=()=>api("/groups").then(setGroups);useEffect(()=>{load()},[]);const add=async()=>{if(!name.trim())return;try{await api("/groups",{method:"POST",body:JSON.stringify({name})});setName("");load()}catch(e:any){alert(e.message)}};const rename=async(g:WorkGroup)=>{const next=prompt(ui("Назва групи","Group name"),g.name);if(!next||next===g.name)return;try{await api(`/groups/${g.id}`,{method:"PATCH",body:JSON.stringify({name:next})});load()}catch(e:any){alert(e.message)}};const remove=async(g:WorkGroup)=>{if(!confirm(`${ui("Видалити","Delete")} ${g.name}?`))return;try{await api(`/groups/${g.id}`,{method:"DELETE"});load()}catch(e:any){alert(e.message)}};return <><div className="hero-row"><div><h1>Групи користувачів</h1><p className="muted">Один користувач може входити до кількох груп.</p></div></div>{user.role==="ADMIN"&&<section className="panel group-create"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Назва групи"/><button className="primary" onClick={add}><Plus/>Додати</button></section>}<div className="group-grid">{groups.map(g=><article className="panel group-card" key={g.id}><div className="section-head"><div><h3>{g.name}</h3><span>{g.members.length} користувачів</span></div>{user.role==="ADMIN"&&<div className="group-actions"><button className="icon" onClick={()=>rename(g)}><Pencil/></button><button className="icon danger-icon" onClick={()=>remove(g)}><Trash2/></button></div>}</div><div className="group-members">{g.members.map(m=><span key={m.user.id}><span className="avatar tiny">{m.user.name[0]}</span>{m.user.name}<small>{roleLabel(m.user.role)}</small></span>)}{!g.members.length&&<span className="muted">Група порожня.</span>}</div></article>)}</div></>}

function EfficiencyPage({user}:{user:User}){const[data,setData]=useState<EfficiencyData|null>(null),[users,setUsers]=useState<User[]>([]),[period,setPeriod]=useState("month"),[userId,setUserId]=useState(user.role==="EMPLOYEE"?user.id:"ALL"),[anchor,setAnchor]=useState(()=>new Date().toISOString().slice(0,10));const load=()=>api(`/efficiency?period=${period}&anchor=${anchor}&userId=${userId}`).then(setData);useEffect(()=>{if(user.role!=="EMPLOYEE")api("/users").then(setUsers);load()},[period,userId,anchor]);const max=Math.max(1,...(data?.trend||[]).map(x=>x.completed+x.overdue));const totals=(data?.summary||[]).reduce((a,x)=>({completed:a.completed+x.completed,overdue:a.overdue+x.overdue,total:a.total+x.total,hours:a.hours+x.avgHours,count:a.count+1}),{completed:0,overdue:0,total:0,hours:0,count:0});return <><div className="hero-row"><div><h1>Ефективність</h1><p className="muted">Виконання, прострочення, швидкість та своєчасність роботи.</p></div></div><section className="panel efficiency-filters"><label>Період<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="day">День</option><option value="week">Тиждень</option><option value="month">Місяць</option><option value="year">Рік</option></select></label><label>Дата<input type="date" value={anchor} onChange={e=>setAnchor(e.target.value)}/></label>{user.role!=="EMPLOYEE"&&<label>Користувач<select value={userId} onChange={e=>setUserId(e.target.value)}><option value="ALL">Усі користувачі</option>{users.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label>}</section><div className="stats stats-four"><Stat icon={<CheckCircle2/>} value={totals.completed} label="Виконано"/><Stat icon={<AlertTriangle/>} value={totals.overdue} label="Прострочено"/><Stat icon={<ClipboardCheck/>} value={totals.total} label="Всього"/><Stat icon={<Clock3/>} value={Math.round((totals.count?totals.hours/totals.count:0)*10)/10} label="Середній час, год."/></div><section className="panel efficiency-chart"><div className="section-head"><h2>Динаміка виконання</h2></div><div className="bars">{data?.trend.map((x,i)=><div className="bar-slot" key={i}><div className="bar-stack"><i className="bar-done" style={{height:`${x.completed/max*100}%`}} title={`${x.completed}`}/><i className="bar-over" style={{height:`${x.overdue/max*100}%`}} title={`${x.overdue}`}/></div><span>{x.label}</span></div>)}{!data?.trend.length&&<div className="empty">Даних за період немає.</div>}</div><div className="chart-legend"><span><i className="legend-done"/>Виконано</span><span><i className="legend-over"/>Прострочено</span></div></section><section className="panel efficiency-table"><div className="section-head"><h2>Показники користувачів</h2></div><div className="table-wrap"><table><thead><tr><th>Користувач</th><th>Всього</th><th>Виконано</th><th>Прострочено</th><th>Вчасно</th><th>Виконання</th><th>Середній час</th></tr></thead><tbody>{data?.summary.map(x=><tr key={x.id}><td><b>{x.name}</b><small>{x.position}</small></td><td>{x.total}</td><td>{x.completed}</td><td>{x.overdue}</td><td>{x.onTimeRate}%</td><td>{x.completionRate}%</td><td>{x.avgHours} год.</td></tr>)}</tbody></table></div></section></>}

function TemplatesPage({user,changed}:{user:User;changed:()=>void}){const[data,setData]=useState<WorkTemplate[]>([]),[query,setQuery]=useState(""),[applied,setApplied]=useState(""),[active,setActive]=useState<WorkTemplate|null>(null),[edit,setEdit]=useState<WorkTemplate|null|undefined>(undefined),[createFrom,setCreateFrom]=useState<WorkTemplate|null>(null);const load=()=>api("/templates").then(setData);useEffect(()=>{load()},[]);const rows=data.filter(x=>`${x.name} ${x.title}`.toLowerCase().includes(applied.toLowerCase()));const remove=async(target:WorkTemplate|null=active)=>{if(!target||!confirm(ui("Видалити шаблон?","Delete template?")))return;try{await api(`/templates/${target.id}`,{method:"DELETE"});if(active?.id===target.id)setActive(null);load()}catch(e:any){alert(e.message)}};return <><div className="hero-row"><div><h1>Шаблони завдань</h1><p className="muted">Створюйте повторювані за змістом завдання та чеклісти без збереження термінів.</p></div></div><section className="panel template-toolbar"><div className="template-search"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Пошук шаблону"/><button onClick={()=>setApplied(query)}><Search/>Пошук</button></div><div className="template-toolbar-actions"><button className="primary" onClick={()=>setEdit(null)}><Plus/>Додати</button><button disabled={!active} onClick={()=>active&&setEdit(active)}><Pencil/>Редагувати</button><button className="danger-icon" disabled={!active} onClick={()=>void remove()}><Trash2/>Видалити</button></div></section><div className="template-grid">{rows.map(x=><article key={x.id} className={`template-card ${active?.id===x.id?"active":""}`} onMouseEnter={()=>setActive(x)} onClick={()=>setActive(x)}><div className="template-card-head"><span className={`kind ${x.type.toLowerCase()}`}>{x.type==="TASK"?<FileCheck2/>:<ClipboardCheck/>}{x.type==="TASK"?"Завдання":"Чекліст"}</span><small>{x.recurrence==="MONTHLY"?"Щомісяця":x.recurrence==="WEEKLY"?"Щотижня":x.recurrence==="CUSTOM_DAYS"?`Кожні ${x.recurrenceDays||1} дн.`:"—"}</small></div><h3>{x.name}</h3><b>{x.title}</b><p>{x.description||"Без опису"}</p><span>{x.type==="CHECKLIST"?`${x.items.length} пунктів`:ui("Окреме завдання","Standalone task")}</span><div className="template-card-actions"><button className="primary" onClick={e=>{e.stopPropagation();setCreateFrom(x)}}><Plus/>Створити із шаблону</button><button onClick={e=>{e.stopPropagation();setEdit(x)}}><Pencil/>Редагувати</button><button className="danger-icon" onClick={e=>{e.stopPropagation();void remove(x)}}><Trash2/>Видалити</button></div></article>)}{!rows.length&&<div className="empty">Шаблонів немає.</div>}</div>{edit!==undefined&&<TemplateEditor template={edit||undefined} close={()=>setEdit(undefined)} done={()=>{setEdit(undefined);load();changed()}}/>}{createFrom&&<WorkEditor template={createFrom} close={()=>setCreateFrom(null)} done={()=>{setCreateFrom(null);load();changed()}}/>}</>}

function TemplateEditor({template,close,done}:{template?:WorkTemplate;close:()=>void;done:()=>void}){const[users,setUsers]=useState<User[]>([]),[f,setF]=useState({name:template?.name||"",type:template?.type||"TASK" as WorkType,title:template?.title||"",description:template?.description||"",recurrence:template?.recurrence||"NONE" as EditorState["recurrence"],recurrenceDays:template?.recurrenceDays||null,assigneeIds:template?.assigneeIds||[] as string[],items:(template?.items||[{title:"",description:"",requiresPhoto:false}]) as EditorItem[]});useEffect(()=>{api("/users").then((u:User[])=>setUsers(u.filter(x=>x.active!==false)))},[]);const item=(i:number,k:keyof EditorItem,v:any)=>setF({...f,items:f.items.map((x,n)=>n===i?{...x,[k]:v}:x)});const toggleUser=(id:string)=>setF({...f,assigneeIds:f.assigneeIds.includes(id)?f.assigneeIds.filter(x=>x!==id):[...f.assigneeIds,id]});const submit=async(e:React.FormEvent)=>{e.preventDefault();try{const payload={...f,items:f.type==="CHECKLIST"?f.items.map(({title,description,requiresPhoto})=>({title,description,requiresPhoto})):[]};await api(template?`/templates/${template.id}`:"/templates",{method:template?"PATCH":"POST",body:JSON.stringify(payload)});done()}catch(e:any){alert(e.message)}};return <div className="modal-backdrop"><form className="modal large-modal" onSubmit={submit}><div className="modal-head"><div><h2>{template?"Редагування шаблону":"Новий шаблон"}</h2><p>Терміни не зберігаються у шаблоні.</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="type-choice"><button type="button" className={f.type==="CHECKLIST"?"active":""} onClick={()=>setF({...f,type:"CHECKLIST"})}><ClipboardCheck/><b>Чекліст</b><span>Набір пунктів</span></button><button type="button" className={f.type==="TASK"?"active":""} onClick={()=>setF({...f,type:"TASK"})}><FileCheck2/><b>Завдання</b><span>Окреме завдання</span></button></div><div className="form-grid"><label className="full">Назва шаблону<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><label className="full">Назва<input required value={f.title} onChange={e=>setF({...f,title:e.target.value})}/></label><label className="full">Опис<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><label>Повторення<select value={f.recurrence} onChange={e=>setF({...f,recurrence:e.target.value as EditorState["recurrence"],recurrenceDays:e.target.value==="CUSTOM_DAYS"?(f.recurrenceDays||1):null})}><option value="NONE">Не повторювати</option><option value="WEEKLY">Щотижня</option><option value="MONTHLY">Щомісяця</option><option value="CUSTOM_DAYS">Кожні N днів</option></select></label>{f.recurrence==="CUSTOM_DAYS"&&<label>Кількість днів<input type="number" min="1" max="365" required value={f.recurrenceDays||1} onChange={e=>setF({...f,recurrenceDays:Math.max(1,Number(e.target.value)||1)})}/></label>}<div className="full template-users"><span className="field-label">Виконавці за замовчуванням</span><div>{users.map(u=><label className="check" key={u.id}><input type="checkbox" checked={f.assigneeIds.includes(u.id)} onChange={()=>toggleUser(u.id)}/>{u.name} · {u.position}</label>)}</div></div></div>{f.type==="CHECKLIST"&&<div className="items-editor"><div className="section-head"><div><h3>Пункти чекліста</h3></div><button type="button" onClick={()=>setF({...f,items:[...f.items,{title:"",description:"",requiresPhoto:false}]})}><Plus/>Додати пункт</button></div>{f.items.map((x,i)=><div className="edit-item" key={i}><span>{i+1}</span><div><input required placeholder="Назва пункту" value={x.title} onChange={e=>item(i,"title",e.target.value)}/><input placeholder="Короткий опис або інструкція" value={x.description||""} onChange={e=>item(i,"description",e.target.value)}/><label className="check"><input type="checkbox" checked={x.requiresPhoto} onChange={e=>item(i,"requiresPhoto",e.target.checked)}/> Вимагати фото</label></div>{f.items.length>1&&<button type="button" className="icon" onClick={()=>setF({...f,items:f.items.filter((_,n)=>n!==i)})}><X/></button>}</div>)}</div>}<div className="modal-actions"><button type="button" onClick={close}>Скасувати</button><button className="primary">Зберегти</button></div></form></div>}

function WorkEditor({work,template,close,done}:{work?:Work;template?:WorkTemplate;close:()=>void;done:()=>void}){const[users,setUsers]=useState<User[]>([]),[groups,setGroups]=useState<WorkGroup[]>([]),[picker,setPicker]=useState(false);const initialIds=work?assignees(work).map(u=>u.id):(template?.assigneeIds||[]);const sourceItems=work?.items?.map(i=>({id:i.id,title:i.title,description:i.description||"",requiresPhoto:i.requiresPhoto}))||template?.items?.map(i=>({title:i.title,description:i.description||"",requiresPhoto:i.requiresPhoto}))||[{title:"",description:"",requiresPhoto:false}];const[f,setF]=useState<EditorState>({type:work?.type||template?.type||"CHECKLIST",title:work?.title||template?.title||"",description:work?.description||template?.description||"",deferred:work?.status==="DEFERRED",startDate:work?.startDate?toLocalInput(work.startDate):toLocalInput(),dueDate:work?.dueDate?toLocalInput(work.dueDate):"",assigneeIds:initialIds,groupIds:[],recurrence:work?.recurrence||template?.recurrence||"NONE",recurrenceDays:work?.recurrenceDays||template?.recurrenceDays||null,items:sourceItems});useEffect(()=>{Promise.all([api("/users").then((u:User[])=>{const a=u.filter(x=>x.active!==false);setUsers(a)}),api("/groups").then(setGroups).catch(()=>setGroups([]))])},[]);const item=(idx:number,k:keyof EditorItem,v:any)=>setF({...f,items:f.items.map((x,i)=>i===idx?{...x,[k]:v}:x)});const addAssignee=(id:string)=>{setF(v=>({...v,assigneeIds:v.assigneeIds.includes(id)?v.assigneeIds:[...v.assigneeIds,id]}));setPicker(false)};const removeAssignee=(id:string)=>setF(v=>({...v,assigneeIds:v.assigneeIds.filter(x=>x!==id)}));const addCurrentToTemplate=async()=>{if(!work)return;try{const name=window.prompt(ui("Назва шаблону","Template name"),work.title);if(!name)return;await api(`/templates/from-checklist/${work.id}`,{method:"POST",body:JSON.stringify({name})});alert(ui("Шаблон додано.","Template added."))}catch(e:any){alert(e.message)}};const submit=async(e:React.FormEvent)=>{e.preventDefault();if(!f.assigneeIds.length&&!f.groupIds.length){alert(ui("Додайте хоча б одного виконавця або групу","Add at least one assignee or group"));return}try{if(!f.deferred&&(!f.startDate||!f.dueDate)){alert(ui("Вкажіть дату початку та термін виконання","Enter a start date and due date"));return}if(!f.deferred&&new Date(f.dueDate)<=new Date(f.startDate)){alert(ui("Термін виконання має бути пізніше дати початку","The due date must be later than the start date"));return}const payload={...f,startDate:f.deferred?null:new Date(f.startDate).toISOString(),dueDate:f.deferred?null:new Date(f.dueDate).toISOString(),items:f.type==="CHECKLIST"?f.items:[]};await api(work?`/checklists/${work.id}`:"/checklists",{method:work?"PATCH":"POST",body:JSON.stringify(payload)});if(template&&window.confirm(ui("Зберегти зміни у шаблоні?","Save changes to the template?"))){await api(`/templates/${template.id}`,{method:"PATCH",body:JSON.stringify({name:template.name,type:f.type,title:f.title,description:f.description,recurrence:f.recurrence,recurrenceDays:f.recurrenceDays,assigneeIds:f.assigneeIds,items:f.type==="CHECKLIST"?f.items.map(({title,description,requiresPhoto})=>({title,description,requiresPhoto})):[]})})}done()}catch(e:any){alert(e.message)}};const available=users.filter(u=>!f.assigneeIds.includes(u.id));return <div className="modal-backdrop"><form className="modal large-modal" onSubmit={submit}><div className="modal-head"><div><h2>{work?"Редагування":template?"Створити із шаблону":"Новий запис"}</h2><p>{work?"Змініть параметри, виконавців, дедлайн або пункти.":template?template.name:"Оберіть чекліст або окреме завдання."}</p></div><button type="button" className="icon" onClick={close}><X/></button></div><div className="type-choice"><button type="button" className={f.type==="CHECKLIST"?"active":""} onClick={()=>setF({...f,type:"CHECKLIST"})}><ClipboardCheck/><b>Чекліст</b><span>Набір пунктів з окремими статусами</span></button><button type="button" className={f.type==="TASK"?"active":""} onClick={()=>setF({...f,type:"TASK"})}><FileCheck2/><b>Завдання</b><span>Один опис і загальний результат</span></button></div><div className="form-grid"><label className="full check deferred-toggle"><input type="checkbox" checked={f.deferred} onChange={e=>setF({...f,deferred:e.target.checked,startDate:e.target.checked?"":(f.startDate||toLocalInput()),dueDate:e.target.checked?"":f.dueDate})}/> Без терміну / Відкласти на невідомий період</label><label className="full">Назва<input required value={f.title} onChange={e=>setF({...f,title:e.target.value})}/></label><label className="full">Опис<textarea value={f.description} onChange={e=>setF({...f,description:e.target.value})}/></label><div className="full assignee-editor"><span className="field-label">Виконавці</span><div className="assignee-chips">{f.assigneeIds.map(id=>{const u=users.find(x=>x.id===id);return u?<span className="assignee-chip" key={id}><span className="avatar tiny">{u.name[0]}</span>{u.name}<button type="button" onClick={()=>removeAssignee(id)}><X/></button></span>:null})}<div className="add-person-wrap"><button type="button" className="add-person" onClick={()=>setPicker(!picker)}><Plus/></button>{picker&&<div className="person-picker">{available.map(u=><button type="button" key={u.id} onClick={()=>addAssignee(u.id)}><span className="avatar tiny">{u.name[0]}</span><span><b>{u.name}</b><small>{u.position}</small></span></button>)}{!available.length&&<div className="picker-empty">Усі користувачі вже додані</div>}</div>}</div></div></div>{groups.length>0&&<div className="full group-assignment"><span className="field-label">Призначити всю групу</span><div className="group-checks">{groups.map(g=><label className="check" key={g.id}><input type="checkbox" checked={f.groupIds.includes(g.id)} onChange={()=>setF(v=>({...v,groupIds:v.groupIds.includes(g.id)?v.groupIds.filter(x=>x!==g.id):[...v.groupIds,g.id]}))}/>{g.name} <small>({g.members.filter(m=>m.user.active!==false).length})</small></label>)}</div></div>}<label>Дата і час початку<input required={!f.deferred} disabled={f.deferred} type="datetime-local" value={f.startDate} onChange={e=>setF({...f,startDate:e.target.value})}/></label><label>Термін виконання<input required={!f.deferred} disabled={f.deferred} type="datetime-local" value={f.dueDate} onChange={e=>setF({...f,dueDate:e.target.value})}/></label><label>Повторення<select value={f.recurrence} onChange={e=>setF({...f,recurrence:e.target.value as EditorState["recurrence"],recurrenceDays:e.target.value==="CUSTOM_DAYS"?(f.recurrenceDays||1):null})}><option value="NONE">Не повторювати</option><option value="WEEKLY">Щотижня</option><option value="MONTHLY">Щомісяця</option><option value="CUSTOM_DAYS">Кожні N днів</option></select></label>{f.recurrence==="CUSTOM_DAYS"&&<label>Кількість днів<input type="number" min="1" max="365" required value={f.recurrenceDays||1} onChange={e=>setF({...f,recurrenceDays:Math.max(1,Number(e.target.value)||1)})}/></label>}</div>{f.type==="CHECKLIST"&&<div className="items-editor"><div className="section-head"><div><h3>Пункти чекліста</h3><span>Фото можна зробити обов'язковим для окремих пунктів.</span></div><button type="button" onClick={()=>setF({...f,items:[...f.items,{title:"",description:"",requiresPhoto:false}]})}><Plus/>Додати пункт</button></div>{f.items.map((x,i)=><div className="edit-item" key={x.id||i}><span>{i+1}</span><div><input required placeholder="Назва пункту" value={x.title} onChange={e=>item(i,"title",e.target.value)}/><input placeholder="Короткий опис або інструкція" value={x.description} onChange={e=>item(i,"description",e.target.value)}/><label className="check"><input type="checkbox" checked={x.requiresPhoto} onChange={e=>item(i,"requiresPhoto",e.target.checked)}/> Вимагати фото</label></div>{f.items.length>1&&<button type="button" className="icon" onClick={()=>setF({...f,items:f.items.filter((_,n)=>n!==i)})}><X/></button>}</div>)}</div>}<div className="modal-actions">{work&&<button type="button" onClick={addCurrentToTemplate}><Plus/>Додати в шаблон</button>}<button type="button" onClick={close}>Скасувати</button><button className="primary">{work?"Зберегти зміни":"Створити"}</button></div></form></div>}

createRoot(document.getElementById("root")!).render(<App/>);
